SELECT es.id, es.event_id, es.subject_id, es.status, es.final_decision, es.eval_duration_ms, es.started_at, MAX(nt.rule_version_id) AS rule_version_id FROM evaluation_session es INNER JOIN node_trace nt ON nt.evaluation_session_id = es.id INNER JOIN rule_version rv ON rv.id = nt.rule_version_id WHERE rv.rule_definition_id = #{ruleDefinitionId}
AND es.status = #{status}
GROUP BY es.id, es.event_id, es.subject_id, es.status, es.final_decision, es.eval_duration_ms, es.started_at ORDER BY es.started_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(DISTINCT es.id)
FROM evaluation_session es
INNER JOIN node_trace nt ON nt.evaluation_session_id = es.id
INNER JOIN rule_version rv ON rv.id = nt.rule_version_id
WHERE rv.rule_definition_id = #{ruleDefinitionId}

    AND es.status = #{status}
